// Deterministic lane battle for the web inspection scene. Balance is exported from C# MatchRules.
export const distance=(a,b)=>Math.hypot(a.X-b.X,a.Y-b.Y);
export function length(route){return route.slice(1).reduce((s,b,i)=>s+distance(route[i],b),0);}
export function at(route,d){for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i],l=distance(a,b);if(d<=l)return {X:a.X+(b.X-a.X)*Math.max(0,d)/l,Y:a.Y+(b.Y-a.Y)*Math.max(0,d)/l};d-=l;}return {...route.at(-1)};}
export function project(route,p){let best=Infinity,result=0,travel=0;for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i],l=distance(a,b),d=Math.max(0,Math.min(l,((p.X-a.X)*(b.X-a.X)+(p.Y-a.Y)*(b.Y-a.Y))/l)),q=at([a,b],d),error=distance(q,p);if(error<best){best=error;result=travel+d;}travel+=l;}return result;}
export class LaneBattle{
 constructor(layout,rules){this.layout=layout;this.rules=rules;this.routes=layout.Lanes.map(x=>x.Points);this.lengths=this.routes.map(length);this.units=[];this.byId=new Map();this.projectiles=[];this.pending=[];this.notices=[];this.time=0;this.wave=0;this.nextWave=rules.FirstWave;this.id=1;this.projectileId=1;this.finished=false;
 for(let team=0;team<2;team++){this.add({kind:'Core',team,position:layout.Bases[team],hp:rules.CoreHealth,damage:rules.TowerDamage,range:11,period:1,radius:2.9});for(const slot of layout.TowerSlots.filter(x=>x.Team===team))this.add({kind:'Tower',team,lane:slot.Lane,tier:slot.Tier,position:slot.Position,hp:rules.TowerHealthByTier[slot.Tier],damage:rules.TowerDamageByTier[slot.Tier],range:11,period:1,radius:1.6});}}
 add(spec){const u={id:this.id++,target:0,lastAttack:-1000,nextAttack:0,spawnedAt:this.time,deadAt:-1000,station:0,...spec};u.maxHp=u.hp;u.structure=u.kind==='Tower'||u.kind==='Core';u.armor=u.structure?30:8;this.units.push(u);this.byId.set(u.id,u);return u;}
 unlocked(u){if(u.kind==='Tower')return !this.units.some(x=>x.hp>0&&x.team===u.team&&x.kind==='Tower'&&x.lane===u.lane&&x.tier<u.tier);if(u.kind==='Core')return [0,1,2].some(lane=>!this.units.some(x=>x.hp>0&&x.team===u.team&&x.kind==='Tower'&&x.lane===lane));return true;}
 targetable(a,b){return b&&b.hp>0&&a.team!==b.team&&this.unlocked(b);}
 reach(a,b){let reach=a.range+(b.structure?b.radius:0);if(!a.structure&&b.kind==='Tower'&&a.lane===b.lane){const q=at(this.routes[a.lane],project(this.routes[a.lane],b.position));reach=Math.max(reach,distance(q,b.position)+this.rules.TowerLaneReachMargin);}return reach;}
 front(a){return this.units.filter(b=>b.hp>0&&b.team!==a.team&&b.kind==='Tower'&&b.lane===a.lane).sort((x,y)=>x.tier-y.tier)[0]??this.units.find(b=>b.hp>0&&b.team!==a.team&&b.kind==='Core');}
 spawnWave(){this.wave++;this.nextWave+=this.rules.WaveInterval;const siege=this.wave%3===0||this.time>=this.rules.LateWaveTime;
 for(let team=0;team<2;team++)for(let lane=0;lane<3;lane++)for(let i=0;i<(siege?4:3);i++){const kind=i<2?'Guard':i===2?'Caster':'Destroyer',r=this.rules;let hp=kind==='Caster'?r.CasterHealth:r.MinionHealth*(kind==='Destroyer'?r.SiegeHealthMultiplier:1),damage=kind==='Caster'?r.CasterDamage:r.MinionDamage*(kind==='Destroyer'?2:1);hp*=1+(this.wave-1)*r.WaveHealthGrowth;damage*=1+(this.wave-1)*r.WaveDamageGrowth;
 const u=this.add({kind,team,lane,hp,damage,range:kind==='Guard'?r.MinionMeleeRange:r.MinionRangedRange,period:kind==='Guard'?r.GuardAttackPeriod:kind==='Caster'?r.CasterAttackPeriod:r.SiegeAttackPeriod,radius:kind==='Guard'?r.GuardRadius:kind==='Caster'?r.CasterRadius:r.SiegeRadius,speed:r.MinionSpeed});let d=4.8+((siege?4:3)-1-i)*r.MinionSpacing;u.station=team?this.lengths[lane]-d:d;u.position=at(this.routes[lane],u.station);
 for(let n=0;n<120&&this.units.some(b=>b!==u&&b.hp>0&&!b.structure&&distance(b.position,u.position)<u.radius+b.radius+r.MinionBodyGap);n++){u.station+=(team?-1:1)*r.MinionSpacing;u.position=at(this.routes[lane],u.station);}}}
 acquire(a){let candidates=this.units.filter(b=>this.targetable(a,b)&&(!b.structure?b.lane===a.lane: b.kind==='Core'||b.lane===a.lane)&&distance(a.position,b.position)<=8+(b.structure?b.radius:0));candidates.sort((x,y)=>(x.structure?1:0)-(y.structure?1:0)||distance(a.position,x.position)-distance(a.position,y.position));return candidates[0];}
 move(a,desired){const fort=this.front(a);if(fort){const gate=project(this.routes[a.lane],fort.position);if(a.team===0&&a.station<=gate)desired=Math.min(desired,gate-.12);if(a.team===1&&a.station>=gate)desired=Math.max(desired,gate+.12);}
 const end=at(this.routes[a.lane],desired),delta={X:end.X-a.position.X,Y:end.Y-a.position.Y},l2=delta.X**2+delta.Y**2;if(l2<1e-9)return;let allowed=1;
 for(const b of this.units){if(b===a||b.hp<=0||b.structure)continue;const sx=a.position.X-b.position.X,sy=a.position.Y-b.position.Y,r=a.radius+b.radius+this.rules.MinionBodyGap,c=sx*sx+sy*sy-r*r,dot=sx*delta.X+sy*delta.Y;if(dot>=0)continue;if(c<=0){allowed=0;break;}const disc=dot*dot-l2*c;if(disc>=0){const hit=(-dot-Math.sqrt(disc))/l2;if(hit>=0&&hit<allowed)allowed=Math.max(0,hit-.0005);}}
 a.station+=(desired-a.station)*allowed;a.position=at(this.routes[a.lane],a.station);}
 attack(a,b){if(this.time+1e-6<a.nextAttack)return;a.nextAttack=this.time+a.period;a.lastAttack=this.time;a.target=b.id;this.pending.push({source:a.id,target:b.id,damage:a.damage*(a.kind==='Destroyer'&&b.structure?this.rules.SiegeStructureMultiplier:1),due:this.time+(a.structure?this.rules.StructureWindup:a.kind==='Destroyer'?this.rules.MinionSiegeWindup:a.kind==='Caster'?this.rules.MinionCasterWindup:this.rules.MinionMeleeWindup)});}
 hit(a,b,damage){if(!b||b.hp<=0||!this.targetable(a,b))return;b.hp=Math.max(0,b.hp-damage*100/(100+b.armor));if(b.hp===0){b.deadAt=this.time;if(b.structure)this.notices.push({time:this.time,text:b.kind==='Core'?'Нексус разрушен':(b.team?'Красная':'Синяя')+' башня разрушена'});if(b.kind==='Core')this.finished=true;}}
 step(dt=.05){if(this.finished)return;this.time+=dt;if(this.time+1e-6>=this.nextWave)this.spawnWave();
 for(let i=this.pending.length-1;i>=0;i--){const p=this.pending[i];if(this.time+1e-6<p.due)continue;this.pending.splice(i,1);const a=this.byId.get(p.source),b=this.byId.get(p.target);if(!a||a.hp<=0||!this.targetable(a,b))continue;if(a.kind==='Guard'){if(distance(a.position,b.position)<=this.reach(a,b)+.6)this.hit(a,b,p.damage);}else this.projectiles.push({...p,id:this.projectileId++,position:{...a.position},team:a.team,kind:a.kind,speed:a.structure?this.rules.StructureProjectileSpeed:a.kind==='Caster'?this.rules.CasterProjectileSpeed:this.rules.SiegeProjectileSpeed,start:distance(a.position,b.position),travel:0});}
 for(let i=this.projectiles.length-1;i>=0;i--){const p=this.projectiles[i],a=this.byId.get(p.source),b=this.byId.get(p.target);if(!b||b.hp<=0){this.projectiles.splice(i,1);continue;}const d=distance(p.position,b.position),step=p.speed*dt;if(d<=step+.25){this.hit(a,b,p.damage);this.projectiles.splice(i,1);}else{p.position.X+=(b.position.X-p.position.X)*step/d;p.position.Y+=(b.position.Y-p.position.Y)*step/d;p.travel+=step;}}
 for(const a of this.units){if(a.hp<=0)continue;let b=this.byId.get(a.target);if(a.structure){if(!this.targetable(a,b)||distance(a.position,b.position)>a.range)b=this.units.filter(x=>!x.structure&&this.targetable(a,x)&&distance(a.position,x.position)<=a.range).sort((x,y)=>distance(a.position,x.position)-distance(a.position,y.position))[0];if(b)this.attack(a,b);continue;}
 if(!this.targetable(a,b))b=this.acquire(a);a.target=b?.id??0;if(b&&distance(a.position,b.position)<=this.reach(a,b)){this.attack(a,b);continue;}let direction=a.team?-1:1;if(b)direction=project(this.routes[a.lane],b.position)>=a.station?1:-1;this.move(a,Math.max(0,Math.min(this.lengths[a.lane],a.station+direction*a.speed*dt)));}
 this.units=this.units.filter(u=>u.structure||u.hp>0||this.time-u.deadAt<2);}
}
